'use client';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import React, {
  type ReactNode, forwardRef, useCallback, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState,
} from 'react';
import './pricing-switch.css';

export interface Plan {
  id: string;
  name: string;
  /** small note next to the name, e.g. "up to 5 seats" */
  note?: string;
  description: string;
  /** USD per month when billed monthly */
  monthly: number;
  /** USD per month when billed yearly */
  yearly: number;
  cta: string;
  features: string[];
  featured?: boolean;
}

export interface PricingSwitchProps {
  plans: Plan[];
  /** heading block shown left of the switch */
  header?: ReactNode;
  /** controlled billing period; leave undefined to let the switch own it */
  yearly?: boolean;
  defaultYearly?: boolean;
  onYearlyChange?: (yearly: boolean) => void;
  /** called when a plan's button is pressed */
  onSelect?: (plan: Plan, yearly: boolean) => void;
  /** badge text shown when Yearly is on */
  yearlyBadge?: string;
  /** label shown on a button right after it's pressed */
  selectedLabel?: (plan: Plan) => string;
  /** force the hover lift on one plan (scripted demos) */
  highlight?: string | null;
  currency?: string;
}

export interface PricingSwitchHandle {
  /** scroll a plan into the middle on phones */
  centre: (id: string, smooth?: boolean) => void;
}

const reduced = () => typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------------- odometer: digit strips 0-9 ×4; every change rolls at least a full turn ---------------- */
function Odometer({ value, dir }: { value: number; dir: number }) {
  const host = useRef<HTMLSpanElement>(null);
  const st = useRef<{ pos: number; n: number; t?: number }[]>([]);
  const digits = String(value).split('').map(Number);
  const first = useRef(true);

  useLayoutEffect(() => {
    const strips = host.current ? [...host.current.querySelectorAll<HTMLSpanElement>('.qd-strip')] : [];
    if (first.current || st.current.length !== strips.length) {
      first.current = false;
      st.current = digits.map((n) => ({ pos: 10 + n, n }));
      strips.forEach((s, i) => { s.style.transition = 'none'; s.style.transform = `translateY(${-st.current[i].pos}em)`; });
      return;
    }
    const L = strips.length; const rm = reduced();
    strips.forEach((s, i) => {
      const o = st.current[i]; const n = digits[i]; const fromRight = L - 1 - i;
      let target: number;
      if (dir > 0) { target = o.pos + ((n - o.n + 10) % 10) + 10; if (target > 39) target -= 10; }
      else { target = o.pos - ((o.n - n + 10) % 10) - 10; if (target < 0) target += 10; }
      if (rm) target = 10 + n;
      const dur = rm ? 0 : 900 + fromRight * 160; const delay = rm ? 0 : (L - 1 - fromRight) * 70;
      s.style.transition = rm ? 'none' : `transform ${dur}ms cubic-bezier(.18,.9,.22,1.04) ${delay}ms`;
      s.style.transform = `translateY(${-target}em)`;
      o.n = n; o.pos = target;
      window.clearTimeout(o.t);
      o.t = window.setTimeout(() => { s.style.transition = 'none'; o.pos = 10 + n; s.style.transform = `translateY(${-o.pos}em)`; }, dur + delay + 60);
    });
    if (rm) host.current?.animate([{ opacity: 0.2 }, { opacity: 1 }], { duration: 250 });
  }, [value]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <span className="qd-odo" aria-hidden="true" ref={host}>
      {digits.map((_, i) => (
        <span className="qd-dg" key={i}>
          <span className="qd-strip">{Array.from({ length: 40 }, (_, k) => <i key={k}>{k % 10}</i>)}</span>
        </span>
      ))}
    </span>
  );
}

function burst(host: HTMLElement, n = 14, dist = 40) {
  for (let i = 0; i < n; i++) {
    const s = document.createElement('i');
    s.className = 'qd-spark';
    const a = (i / n) * Math.PI * 2 + Math.random() * 0.4; const d = dist * (0.7 + Math.random() * 0.6);
    if (i % 3 === 1) s.style.background = '#F4F4F6';
    if (i % 3 === 2) s.style.background = '#8B6CFF';
    host.appendChild(s);
    s.animate(
      [{ transform: 'translate(0,0) scale(1)', opacity: 1 }, { transform: `translate(${Math.cos(a) * d}px,${Math.sin(a) * d}px) scale(.2)`, opacity: 0 }],
      { duration: 600 + Math.random() * 250, easing: 'cubic-bezier(.1,.8,.3,1)' },
    ).onfinish = () => s.remove();
  }
}

const Check = () => (
  <svg aria-hidden="true" viewBox="0 0 20 20"><circle className="qd-cbg" cx="10" cy="10" r="10" /><path className="qd-ck" d="m5.8 10.4 2.7 2.7 5.7-6" pathLength={1} fill="none" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" /></svg>
);
const Arrow = () => (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6" /></svg>);
const Tick = () => (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round"><path d="m5 12.5 4.5 4.5L19 7.5" /></svg>);
const Gift = () => (<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 12v9H4v-9M2 7h20v5H2zM12 21V7M12 7H7.5a2.5 2.5 0 1 1 0-5C11 2 12 7 12 7Zm0 0h4.5a2.5 2.5 0 1 0 0-5C13 2 12 7 12 7Z" /></svg>);

/* ---------------- the component ---------------- */
export const PricingSwitch = forwardRef<PricingSwitchHandle, PricingSwitchProps>(function PricingSwitch({
  plans, header, yearly: controlled, defaultYearly = false, onYearlyChange, onSelect,
  yearlyBadge = '2 months free', selectedLabel = (p) => (p.featured ? `${p.name} selected` : 'Selected'),
  highlight = null, currency = '$',
}, ref) {
  const [inner, setInner] = useState(defaultYearly);
  const yearly = controlled ?? inner;
  const rm = useReducedMotion() ?? false;
  const [dir, setDir] = useState(0);
  const [sweepKey, setSweepKey] = useState(0);
  const [boost, setBoost] = useState(false);
  const [chosen, setChosen] = useState<string | null>(null);
  const [active, setActive] = useState(Math.max(0, plans.findIndex((p) => p.featured)));
  const [live, setLive] = useState('');
  const badge = useRef<HTMLSpanElement>(null);
  const cardsEl = useRef<HTMLDivElement>(null);
  const featsRefs = useRef<(HTMLUListElement | null)[]>([]);
  const prev = useRef(yearly);
  const bM = useRef<HTMLButtonElement>(null);
  const bY = useRef<HTMLButtonElement>(null);

  const redraw = useCallback(() => {
    featsRefs.current.forEach((u) => { if (!u) return; u.classList.remove('drawn'); void u.offsetWidth; u.classList.add('drawn'); });
  }, []);
  useEffect(() => { requestAnimationFrame(redraw); }, [redraw]);

  // every change of period: direction, sweep, boost, redraw, announce
  useEffect(() => {
    if (prev.current === yearly) return;
    prev.current = yearly;
    setDir(yearly ? 1 : -1);
    redraw();
    if (!rm) {
      setSweepKey((k) => k + 1);
      setBoost(true);
      if (yearly && badge.current) burst(badge.current, 12, 34);
    }
    setLive(yearly ? `Yearly billing. ${yearlyBadge}.` : 'Monthly billing.');
    const k = setTimeout(() => setBoost(false), 1100);
    return () => clearTimeout(k);
  }, [yearly, rm, redraw, yearlyBadge]);

  const set = (y: boolean) => { if (y === yearly) return; if (controlled === undefined) setInner(y); onYearlyChange?.(y); };

  const centre = useCallback((id: string, smooth = true) => {
    const host = cardsEl.current; const c = host?.querySelector<HTMLElement>(`[data-plan="${id}"]`);
    if (!host || !c) return;
    host.scrollTo({ left: c.offsetLeft - (host.clientWidth - c.offsetWidth) / 2, behavior: smooth && !reduced() ? 'smooth' : 'auto' });
  }, []);
  useImperativeHandle(ref, () => ({ centre }), [centre]);
  useEffect(() => {
    const f = plans.find((p) => p.featured);
    if (f && window.matchMedia('(max-width:900px)').matches) centre(f.id, false);
  }, [plans, centre]);

  const choose = (p: Plan, el: HTMLElement) => {
    if (chosen) return;
    setChosen(p.id);
    if (!rm) burst(el, 16, 60);
    setLive(`${p.name} plan selected, ${yearly ? 'yearly' : 'monthly'} billing.`);
    onSelect?.(p, yearly);
    setTimeout(() => setChosen(null), 1400);
  };

  return (
    <section className="qd-pricing" aria-label="Pricing">
      <div className="qd-ps-top">
        <div>{header}</div>
        <div className="qd-sw-wrap">
          <div
            className={`qd-seg${yearly ? ' y' : ''}`}
            data-dir={dir || undefined}
            role="radiogroup"
            aria-label="Billing period"
            onKeyDown={(e) => {
              if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) return;
              e.preventDefault();
              const y = e.key === 'Home' ? false : e.key === 'End' ? true : !yearly;
              set(y); (y ? bY : bM).current?.focus();
            }}
          >
            <span className="qd-pill" aria-hidden="true" />
            <button ref={bM} data-bill="m" role="radio" aria-checked={!yearly} tabIndex={yearly ? -1 : 0} onClick={() => set(false)}>Monthly</button>
            <button ref={bY} data-bill="y" role="radio" aria-checked={yearly} tabIndex={yearly ? 0 : -1} onClick={() => set(true)}>Yearly</button>
          </div>
          <span ref={badge} className={`qd-badge${yearly ? ' on' : ''}`}><Gift />{yearlyBadge}</span>
        </div>
      </div>

      <div
        ref={cardsEl}
        className={`qd-cards${yearly ? ' on-y' : ''}`}
        onScroll={(e) => {
          const host = e.currentTarget; const mid = host.scrollLeft + host.clientWidth / 2;
          let k = 0; let best = 1e9;
          [...host.children].forEach((c, i) => { const el = c as HTMLElement; const d = Math.abs(el.offsetLeft + el.offsetWidth / 2 - mid); if (d < best) { best = d; k = i; } });
          setActive(k);
        }}
      >
        {plans.map((p, ci) => {
          const v = yearly ? p.yearly : p.monthly;
          const billed = yearly ? `${currency}${p.yearly * 12} billed yearly` : 'billed monthly';
          return (
            <article
              key={p.id}
              data-plan={p.id}
              aria-labelledby={`qd-n-${p.id}`}
              className={`qd-card${p.featured ? ' feat' : ''}${highlight === p.id ? ' hov' : ''}${sweepKey ? ' sweep' : ''}${p.featured && boost ? ' boost' : ''}`}
              style={{ ['--d' as string]: `${ci * 0.08}s` } as React.CSSProperties}
            >
              {p.featured && (<><div className="qd-halo" aria-hidden="true" /><div className="qd-ring" aria-hidden="true"><i /></div><span className="qd-tag">MOST POPULAR</span></>)}
              <div className="qd-shine" aria-hidden="true" key={`s${sweepKey}`} />
              <div className="qd-pname"><h2 id={`qd-n-${p.id}`}>{p.name}</h2>{p.note && <span>{p.note}</span>}</div>
              <p className="qd-pdesc">{p.description}</p>
              <div className="qd-price">
                <span className="qd-cur" aria-hidden="true">{currency}</span>
                <Odometer value={v} dir={dir} />
                <span className="qd-per" aria-hidden="true">/mo</span>
                <span className="qd-sr">{`${currency}${v} per month, ${billed}`}</span>
              </div>
              <div className="qd-sub">
                <p>{billed}</p>
                <span className="qd-save" style={{ ['--d' as string]: `${0.25 + ci * 0.08}s` } as React.CSSProperties}>{`SAVE ${currency}${(p.monthly - p.yearly) * 12}/YR`}</span>
              </div>
              <button className="qd-cta" onClick={(e) => choose(p, e.currentTarget)}>
                <AnimatePresence mode="wait" initial={false}>
                  <motion.span
                    key={chosen === p.id ? 'on' : 'off'}
                    style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}
                    initial={rm ? { opacity: 0 } : { opacity: 0, y: 8, scale: 0.9 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={rm ? { opacity: 0 } : { opacity: 0, y: -8, scale: 0.9 }}
                    transition={{ duration: rm ? 0.12 : 0.18 }}
                  >
                    {chosen === p.id ? (<><Tick />{selectedLabel(p)}</>) : (<>{p.cta}<Arrow /></>)}
                  </motion.span>
                </AnimatePresence>
              </button>
              <ul className="qd-feats" ref={(el) => { featsRefs.current[ci] = el; }}>
                {p.features.map((f, k) => (
                  <li key={f} style={{ ['--d' as string]: `${ci * 0.08 + k * 0.06}s` } as React.CSSProperties}><Check />{f}</li>
                ))}
              </ul>
            </article>
          );
        })}
      </div>
      <div className="qd-dots-m" aria-hidden="true">{plans.map((p, i) => <i key={p.id} className={i === active ? 'on' : ''} />)}</div>
      <p className="qd-sr" aria-live="polite">{live}</p>
    </section>
  );
});

export default PricingSwitch;

/* Pricing Switch · qodesign · MIT. Tokens: change the values here. */
.qd-pricing{
  --volt:#C6FF3D; --ultra:#8B6CFF; --text:#F4F4F6; --muted:#8A8FA3; --faint:#5C6378;
  --ink:#0A0A0D; --panel:#121319; --line:#262A36; --line2:#323747;
  --spring:cubic-bezier(.32,1.42,.56,1); --out:cubic-bezier(.16,1,.3,1);
  font-family:'Space Grotesk',system-ui,sans-serif; color:var(--text);
}
.qd-pricing button{font:inherit;color:inherit;cursor:pointer}
.qd-pricing :focus-visible{outline:2px solid var(--volt);outline-offset:3px}
.qd-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.qd-ps-top{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;flex-wrap:wrap}
.qd-pricing{display:flex;flex-direction:column;min-height:0;flex:1}
/* segmented switch */
.qd-sw-wrap{display:flex;align-items:center;gap:14px;position:relative}
.qd-seg{position:relative;display:grid;grid-template-columns:1fr 1fr;padding:5px;border-radius:99px;background:#16171F;border:1px solid var(--line2);box-shadow:inset 0 2px 8px rgba(0,0,0,.4)}
.qd-seg .qd-pill{position:absolute;top:5px;bottom:5px;left:5px;right:50%;border-radius:99px;background:var(--volt);box-shadow:0 6px 24px rgba(198,255,61,.35),inset 0 1px 0 rgba(255,255,255,.5);transition:left .42s var(--spring),right .42s var(--spring)}
.qd-seg[data-dir="1"] .qd-pill{transition:right .34s var(--spring),left .46s var(--spring) .07s}
.qd-seg[data-dir="-1"] .qd-pill{transition:left .34s var(--spring),right .46s var(--spring) .07s}
.qd-seg.y .qd-pill{left:50%;right:5px}
.qd-seg button{position:relative;z-index:1;min-width:116px;height:46px;border:0;background:none;border-radius:99px;font-size:15px;font-weight:700;color:var(--muted);transition:color .3s}
.qd-seg button[aria-checked="true"]{color:var(--ink)}
.qd-seg button.press{transform:scale(.96)}
.qd-badge{position:relative;display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 13px;border-radius:99px;background:var(--ultra);color:#fff;font:700 13px 'Space Grotesk';white-space:nowrap;transform:scale(0) rotate(-14deg);opacity:0;transition:transform .5s var(--spring),opacity .2s;box-shadow:0 8px 26px rgba(139,108,255,.45)}
.qd-badge.on{transform:scale(1) rotate(-4deg);opacity:1}
.qd-badge svg{width:14px;height:14px}
.qd-spark{position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px;border-radius:50%;background:var(--volt);pointer-events:none}
/* cards */
.qd-cards{flex:1;display:grid;grid-template-columns:1fr 1.08fr 1fr;gap:18px;align-items:center;padding:26px 6px 28px;min-height:0}
.qd-card{position:relative;border-radius:24px;background:var(--panel);border:1px solid var(--line);padding:24px 24px 22px;display:flex;flex-direction:column;transition:transform .5s var(--spring),border-color .3s,box-shadow .5s;isolation:isolate}
.qd-card:hover,.qd-card.hov{transform:translateY(-8px);border-color:#3A3F52;box-shadow:0 30px 60px rgba(0,0,0,.45)}
.qd-card.feat{transform:translateY(-12px) scale(1.02);border-color:transparent;background:#14151D;box-shadow:0 40px 90px rgba(0,0,0,.55)}
.qd-card.feat:hover,.qd-card.feat.hov{transform:translateY(-18px) scale(1.025)}
.qd-card .qd-ring{position:absolute;inset:-1px;border-radius:inherit;padding:2px;pointer-events:none;-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0);overflow:hidden;z-index:2}
.qd-card .qd-ring i{position:absolute;left:50%;top:50%;width:160%;aspect-ratio:1;translate:-50% -50%;background:conic-gradient(from 0deg,var(--volt),#6EE7B7 18%,var(--ultra) 40%,rgba(139,108,255,.15) 55%,rgba(198,255,61,.15) 75%,var(--volt));animation:qd-spin 4s linear infinite}
.qd-card.feat.boost .qd-ring i{animation-duration:.9s}
.qd-card .qd-halo{position:absolute;inset:-30px -20px;z-index:-1;border-radius:40px;background:radial-gradient(60% 50% at 50% 0%,rgba(139,108,255,.35),transparent 70%),radial-gradient(60% 45% at 50% 100%,rgba(198,255,61,.18),transparent 70%);filter:blur(24px);opacity:.8;pointer-events:none;animation:qd-ps-breathe 3.2s ease-in-out infinite}
@keyframes qd-spin{to{transform:rotate(360deg)}}
@keyframes qd-ps-breathe{50%{opacity:.45}}
.qd-shine{position:absolute;inset:0;border-radius:inherit;pointer-events:none;overflow:hidden}
.qd-shine::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.10) 48%,rgba(198,255,61,.10) 52%,transparent 65%);transform:translateX(-120%)}
.qd-card.sweep .qd-shine::after{animation:qd-sweep .9s var(--out) forwards;animation-delay:var(--d,0s)}
@keyframes qd-sweep{to{transform:translateX(120%)}}
.qd-tag{position:absolute;top:-13px;left:50%;translate:-50% 0;height:26px;padding:0 12px;border-radius:99px;background:var(--volt);color:var(--ink);font:700 12px 'JetBrains Mono';display:flex;align-items:center;letter-spacing:.4px;z-index:3;white-space:nowrap}
.qd-pname{display:flex;align-items:center;justify-content:space-between;gap:10px}
.qd-pname h2{margin:0;font-size:19px;font-weight:700}
.qd-pname span{font:500 12px 'JetBrains Mono';color:var(--faint)}
.qd-pdesc{margin:6px 0 0;color:var(--muted);font-size:13.5px;line-height:1.4;min-height:38px}
.qd-price{display:flex;align-items:flex-start;gap:3px;margin-top:14px;height:78px}
.qd-cur{font:800 30px/1 'Saira Condensed';margin-top:8px;color:var(--text)}
.qd-odo{display:flex;font:800 80px/1 'Saira Condensed';letter-spacing:-.5px}
.qd-dg{display:block;height:1em;overflow:hidden;-webkit-mask:linear-gradient(transparent,#000 14%,#000 86%,transparent);mask:linear-gradient(transparent,#000 14%,#000 86%,transparent)}
.qd-strip{display:flex;flex-direction:column;will-change:transform}
.qd-strip i{font-style:normal;height:1em;display:block;text-align:center}
.qd-per{align-self:flex-end;margin:0 0 12px 6px;color:var(--muted);font-size:14px;font-weight:500}
.qd-sub{position:relative;height:30px;margin-top:4px;display:flex;align-items:center;gap:8px}
.qd-sub p{margin:0;font-size:13px;color:var(--muted);transition:opacity .3s}
.qd-save{display:inline-flex;align-items:center;height:24px;padding:0 9px;border-radius:99px;background:rgba(198,255,61,.12);color:var(--volt);font:700 12px 'JetBrains Mono';transform:scale(.4);opacity:0;transition:transform .45s var(--spring),opacity .2s;transition-delay:var(--d,0s)}
.on-y .qd-save{transform:none;opacity:1}
.qd-cta{position:relative;margin-top:16px;min-height:48px;border-radius:14px;border:1px solid var(--line2);background:#1A1B24;font-size:15px;font-weight:700;display:flex;align-items:center;justify-content:center;gap:8px;transition:transform .15s,background .2s}
.qd-cta:hover{background:#22242F}
.qd-cta:active,.qd-cta.press{transform:scale(.96)}
.feat .qd-cta{background:var(--volt);color:var(--ink);border-color:var(--volt);box-shadow:0 10px 30px rgba(198,255,61,.25)}
.feat .qd-cta:hover{background:#D4FF6A}
.qd-cta svg{width:18px;height:18px}
.qd-feats{list-style:none;margin:18px 0 0;padding:18px 0 0;border-top:1px solid #20222D;display:flex;flex-direction:column;gap:11px}
.qd-feats li{display:flex;align-items:center;gap:10px;font-size:14px;color:#D9DBE3}
.qd-feats svg{width:20px;height:20px;flex:none}
.qd-feats .qd-cbg{fill:rgba(198,255,61,.12)}
.feat .qd-feats .qd-cbg{fill:var(--volt)}
.qd-feats .qd-ck{stroke:var(--volt);stroke-dasharray:1;stroke-dashoffset:1}
.feat .qd-feats .qd-ck{stroke:var(--ink)}
.drawn .qd-ck{stroke-dashoffset:0;transition:stroke-dashoffset .45s var(--out);transition-delay:var(--d,0s)}
.qd-dots-m{display:none}

@media (max-width:900px){
  .qd-ps-top{padding:0 20px;flex-direction:column;align-items:flex-start;gap:16px}
  .qd-cards{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;padding:30px 20px 16px;align-items:stretch;scrollbar-width:none;flex:none}
  .qd-cards::-webkit-scrollbar{display:none}
  .qd-card{flex:0 0 min(300px,78vw);scroll-snap-align:center}
  .qd-card.feat{transform:none}.qd-card.feat:hover,.qd-card.feat.hov,.qd-card:hover,.qd-card.hov{transform:none}
  .qd-dots-m{display:flex;justify-content:center;gap:7px;padding:4px 0 14px}
  .qd-dots-m i{width:7px;height:7px;border-radius:99px;background:#2E3240;transition:width .3s,background .3s}
  .qd-dots-m i.on{width:22px;background:var(--volt)}
}
@media (max-width:640px){
  .qd-seg button{min-width:110px}
  .qd-badge{position:absolute;right:-10px;top:-20px;height:28px;font-size:12px;padding:0 11px;z-index:2}
  .qd-sw-wrap{margin-top:8px}
  .qd-odo{font-size:68px}.qd-price{height:68px}
  .qd-pdesc{min-height:0}
  .qd-feats{gap:9px;margin-top:14px;padding-top:14px}
}
@media (prefers-reduced-motion:reduce){
  .qd-seg .qd-pill,.qd-seg[data-dir] .qd-pill{transition:left .15s,right .15s}
  .qd-badge{transition:opacity .2s;transform:rotate(-4deg)}
  .qd-card,.qd-card .qd-ring i,.qd-card .qd-halo{transition:none;animation:none}
  .qd-card.sweep .qd-shine::after{animation:none}
  .qd-save{transform:none;transition:opacity .2s}
  .drawn .qd-ck{transition:none}
  .qd-cta:active,.qd-cta.press{transform:none}
}
